/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

M2C_UNK updateActiveMenuState();                            /* extern */
M2C_UNK updateSaveMenuRowHighlight(s32, M2C_UNK, M2C_UNK);       /* extern */
M2C_UNK scaleVoiceValueByFactor(s32);                         /* extern */
M2C_UNK drawMenuList(s32);                         /* extern */
extern s32 gMenuList;

/* Per-frame menu step: scales voice value, draws the menu list, updates menu state and the save row highlight. */ void updateAndDrawMenuList(void) {
    scaleVoiceValueByFactor(gMenuList);
    drawMenuList(gMenuList);
    updateActiveMenuState();
    updateSaveMenuRowHighlight(gMenuList, 2, 0);
}
